                        x: xAxis,
                        y: Array.isArray(s.meridionalFirst) ? s.meridionalFirst : [],
                        type: 'scatter',
                        mode: 'lines',
                        name: 'Meridional ' + firstFreqText + ' lp/mm (' + nm + 'nm)',
                        line: { color, width: 2, dash: 'solid' },
